import XCTest
final class PinTests: XCTestCase {
    func testSavesFoundIDOnce() throws {
        let spy = PinsSpy()
        let source = BooksStub(values: [71: Book(id: 71, title: "Орбита")])
        let sut = PinBook(source: source, pins: spy)
        try sut.execute(id: 71)
        XCTAssertEqual(spy.ids, [71])
    }
    func testMissingDoesNotSave() {
        let spy = PinsSpy()
        let sut = PinBook(source: BooksStub(values: [:]), pins: spy)
        XCTAssertThrowsError(try sut.execute(id: 72))
        XCTAssertEqual(spy.ids, [])
    }
}

