import XCTest
struct ReadingBook { let id: Int; let finished: Bool }
struct ReadingSummary {
    func finishedCount(_ values: [ReadingBook]) -> Int {
        values.filter { $0.finished }.count
    }
}
final class SummaryTests: XCTestCase {
    func testMixed() {
        let values = [ReadingBook(id: 71, finished: true),
                      ReadingBook(id: 72, finished: false)]
        XCTAssertEqual(ReadingSummary().finishedCount(values), 1)
    }
    func testEmpty() {
        XCTAssertEqual(ReadingSummary().finishedCount([]), 0)
    }
}

